// @ts-check
import starlight from "@astrojs/starlight";
import { defineConfig } from "astro/config";
import starlightLlmsTxt from "starlight-llms-txt";
import { markdownIndexCopies } from "./src/integrations/markdown-index-copies";

/**
 * The docs host. `docs.suite.run` serves this site at its root; the app is
 * `app.suite.run` and the marketing page is `suite.run` (ADR-0079).
 *
 * `src/content/docs/` is generated by `scripts/sync-docs.mjs` from `docs/` on
 * every `dev` and `build`, so nothing in it is edited by hand. The dashboard is
 * the one page this app owns: it lives in `src/pages/index.astro` and reads the
 * collection.
 */
export default defineConfig({
  site: "https://docs.suite.run",
  // The Fumadocs site put every page under `/docs`; the Starlight site is the
  // root of its own host, so the old entry point forwards to the dashboard.
  redirects: {
    "/docs": "/",
  },
  integrations: [
    markdownIndexCopies(),
    starlight({
      title: "Suite",
      description:
        "Documentation for Suite, a local-first collaborative canvas with a typed object graph.",
      customCss: ["./src/styles/docs.css"],
      social: [
        {
          icon: "github",
          label: "GitHub",
          href: "https://github.com/mr-rogers-neighborhood/suite-canvas",
        },
      ],
      editLink: {
        baseUrl: "https://github.com/mr-rogers-neighborhood/suite-canvas/edit/main/docs/",
      },
      // Autogeneration replaces the `meta.json` files the Fumadocs build needed:
      // the directories are the sections, so the sidebar is configuration.
      sidebar: [
        { label: "Overview", link: "/overview/" },
        { label: "Tutorials", items: [{ autogenerate: { directory: "tutorials" } }] },
        { label: "How-to", items: [{ autogenerate: { directory: "how-to" } }] },
        { label: "Reference", items: [{ autogenerate: { directory: "reference" } }] },
        { label: "Explanation", items: [{ autogenerate: { directory: "explanation" } }] },
        {
          label: "For agents",
          items: [
            { label: "llms.txt", link: "/llms.txt" },
            { label: "llms-full.txt", link: "/llms-full.txt" },
          ],
        },
      ],
      plugins: [
        starlightLlmsTxt({
          projectName: "Suite",
          description:
            "Suite is a local-first collaborative canvas: one Loro document per workspace, a typed object graph validated by @suite/graph, and a React 19 canvas.",
          details:
            "The documentation has four sections: tutorials, how-to, reference and explanation. Every page is also served as Markdown: drop the trailing slash from its URL and append `.md`.",
          optionalLinks: [
            {
              label: "Suite app",
              url: "https://app.suite.run",
              description: "the canvas this documentation describes",
            },
            {
              label: "Source",
              url: "https://github.com/mr-rogers-neighborhood/suite-canvas",
              description: "the repository the pages are written in",
            },
          ],
          // The rendered page carries a heading anchor link whose screen-reader
          // label ("Section titled …") is noise once the page is text.
          customSelectors: { all: ["a.sl-anchor-link"] },
          promote: ["overview", "*/index"],
        }),
      ],
    }),
  ],
});
